@RestController
@RequestMapping("/api/v1/orders")
public class OrderController {

    private final FeatureFlagService featureFlagService;
    private final OrderServiceV2 orderServiceV2;
    private final OrderServiceV1 orderServiceV1;

    public OrderController(FeatureFlagService featureFlagService, 
                           OrderServiceV2 orderServiceV2, 
                           OrderServiceV1 orderServiceV1) {
        this.featureFlagService = featureFlagService;
        this.orderServiceV2 = orderServiceV2;
        this.orderServiceV1 = orderServiceV1;
    }

    @PostMapping
    public ResponseEntity<OrderResponse> createOrder(@RequestBody OrderRequest request) {
        // Safe deployment pattern: Fallback to V1 logic dynamically if V2 flags an anomaly
        if (featureFlagService.isEnabled("use-legacy-order-pipeline")) {
            return ResponseEntity.ok(orderServiceV1.process(request));
        }
        try {
            return ResponseEntity.ok(orderServiceV2.process(request));
        } catch (Exception e) {
            // Automated circuit breaking / fallback mechanism during partial deployment degradation
            return ResponseEntity.ok(orderServiceV1.process(request));
        }
    }
}
